import{_ as t,o,c as a,a2 as s}from"./chunks/framework.Desnpdez.js";const p=JSON.parse('{"title":"Welcome","description":"","frontmatter":{},"headers":[],"relativePath":"welcome.md","filePath":"welcome.md"}'),n={name:"welcome.md"};function r(i,e,l,c,h,d){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h1><p><strong>MindBehindAI</strong> is a desktop app from <strong>MindBehind IT</strong> for <strong>macOS</strong> and <strong>Windows</strong> that helps you use the same <em>connections</em> (tools and data sources) in assistants such as <strong>ChatGPT</strong>, <strong>MBIT Chat</strong> (or any compatible chat server), or other apps that accept a server link.</p><p>You stay in control: connections and credentials live on your computer. The app runs a local <strong>assistant bridge</strong> so those assistants can call your tools over simple HTTP links.</p><h2 id="what-you-do-in-practice" tabindex="-1">What you do in practice <a class="header-anchor" href="#what-you-do-in-practice" aria-label="Permalink to &quot;What you do in practice&quot;">​</a></h2><ol><li>Add connections (from the built-in <strong>Library</strong> or by hand).</li><li>On <strong>Home</strong>, turn the <strong>assistant bridge</strong> on.</li><li>Copy each connection’s <strong>link</strong> and paste it where your assistant asks for a tool URL—or use <strong>MBIT Chat</strong> under Integrations to sync automatically.</li></ol><p>You do <strong>not</strong> need to be a developer. Technical details are optional and live under <strong>Reference</strong> in the sidebar.</p><h2 id="names-you-will-see" tabindex="-1">Names you will see <a class="header-anchor" href="#names-you-will-see" aria-label="Permalink to &quot;Names you will see&quot;">​</a></h2><ul><li><strong>MindBehindAI</strong> is the app and product name (including the window title).</li><li><strong>Assistant bridge</strong> is the friendly name for the local gateway that speaks to your assistants.</li><li><strong>Connections</strong> are the entries you configure—each becomes one address like <code>http://localhost:8000/…</code>.</li></ul><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><p>Teams and individuals who already use or plan to use <strong>MCP</strong>-capable assistants and want a guided, local-first way to attach Telekom Telecontext, Microsoft 365, Obsidian, or custom servers—without typing shell commands.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Follow the <strong><a href="./quick-start.html">Quick start</a></strong> once, then use the <strong>Everyday use</strong> pages whenever you need a reminder.</p>',12)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
